/*mSearch 1.0*/
$(document).ready(function()
{
    var toggleBar = $('<div id="searchToggleBarDiv"><span id="searchToggleBarSpan"></span></div>');
    var searchBar = $('<div id="searchBarDiv"><input type="text" value="" id="searchInput"/></div>');
    var searchBarClose = $('<div id="searchBarCloseIconDiv"><a id="searchClose" href="javascript:resetSearch();"><img border="0" src="msearch/img/close.png" alt=""/></a></div>');
    var searchBarMag = $('<div id="searchBarMagIconDiv"><img border="0" src="msearch/img/mag.png" alt=""/></div>');
    var typeSelect = $('<div id="searchSelectWindow"></div>');
    var container = $('<div id="searchContainerDiv"/>');
    var searchDiv = $('<div id="searchFrameDiv"/>');
    var list = $('<ul id="searchItemList"></ul>');

    var searchFilter = "All";
    if(readCookie('searchFilter'))
        searchFilter = readCookie('searchFilter');

    var searchType = "Contains...";
    if(readCookie('searchType'))
        searchType = readCookie('searchType');

    var htmlTypes = '<div id="searchFilter">';
    htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchFilter == 'All' ? '&#8226;' : '&#160;') + '</span><span class="itm">All</span></a>';

    for (var i=0; i<types.length; ++i )
        htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchFilter == types[i] ? '&#8226;' : '&#160;') + '</span><span class="itm">'+types[i]+'</span></a>';

    htmlTypes += '</div>';
    htmlTypes += '<div id="searchType">';
    htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchType == "Contains..." ? '&#8226;' : '&#160;') + '</span><span class="itm">Contains...</span></a>';
    htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchType == "Starts with..." ? '&#8226;' : '&#160;') + '</span><span class="itm">Starts with...</span></a>';
    htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchType == "Ends with..." ? '&#8226;' : '&#160;') + '</span><span class="itm">Ends with...</span></a>';
    htmlTypes += '<a class="SelectItem" href="javascript:void(0)"><span class="SelectionMark">' + (searchType == "RegEx" ? '&#8226;' : '&#160;') + '</span><span class="itm">RegEx</span></a>';
    htmlTypes += '</div>';

    if(window.location.href.indexOf('http://') == -1) {
        htmlTypes += '<div id="searchOffline">';
        htmlTypes += '<a class="SelectItem" href="search.html"><span class="itm">Fulltext (ALPHA)</span></a>';
        htmlTypes += '</div>';
    }


    htmlTypes = $(htmlTypes);
    typeSelect.append($(htmlTypes));
    searchBarMag.append(typeSelect);

    $('#side-nav').prepend(container);
    searchBar.append(searchBarMag);
    searchBar.append(searchBarClose);
    searchDiv.append(list);

    container.append(toggleBar);
    container.append(searchBar);
    container.append(searchDiv);

    $('#side-nav').css('height', $(window).height() - $('#searchContainerDiv').height() + "px");

    $('#searchInput').keyup(function(e)
    {
        var key = e.which || e.keyCode || e.keyChar;

        if (key != 33 && key != 34 && key != 35 && key != 38 && key != 40 && key != 13)
        {
            var searchInput = $(this).attr('value').ltrim().rtrim().doublewhitetrim();

            writeCookie('searchInput', searchInput, null);
            writeCookie('searchInputPos', $(this).getSelection().start, null);
            writeCookie('searchLastSelection', false, null);

            buildList(list, searchInput, searchFilter, searchType);

            searchInput == "" ?  $('#searchBarCloseIconDiv').hide() : $('#searchBarCloseIconDiv').show();

            highlightContents();

            $('#searchFrameDiv').animate({scrollTop: 0}, 0.001);
        }
        else
        {
            highlightContents();

            if(key == 33 || key == 34 || key == 35)
            {
                var itm, node, container, height, itmHeight, count, sc;

                container = $('#searchFrameDiv');

                if(key == 33 || key == 34)
                {
                    itm = $('.searchItemSelected').first();
                    height = getMaxHeight();
                    itmHeight = itm.height();
                    count = height/itmHeight-2;
                }

                $('#searchFrameDiv li').removeClass('searchItemSelected');

                if(key == 33)
                {
                    node = itm.prevAll().eq(count);
                    if (node.attr('class') != "searchItem")
                    {
                        node = $('#searchFrameDiv li').first();
                        sc = 0;
                    }

                    sc = container.scrollTop() + node.position().top - ($('#searchBarDiv').height() + $('#searchToggleBarDiv').height()) - 4;
                }

                if(key == 34)
                {
                    node = itm.nextAll().eq(count);
                    if (node.attr('class') != "searchItem")
                    {
                        node = $('#searchFrameDiv li').last();
                        sc = 999999;
                    }

                    sc = container.scrollTop() + node.position().top - container.height() - itmHeight - 7;
                }

                if(key == 35)
                {
                    node = $('#searchFrameDiv li').last();
                    sc = 999999;
                }

				container.stop().animate({scrollTop: sc}, 0);

				node.addClass('searchItemSelected');
				writeCookie('searchLastSelection', node.text().hash() + node.find('a').attr('href'), null);
            }
        }
    });

    $('#searchInput').keydown(checkNavKeys);

    function checkNavKeys(e)
    {
        var key = e.which || e.keyCode || e.keyChar;

        if (key == 38 || key == 40 || key == 13)
        {
            var items = $('#searchFrameDiv li');
            var selected = items.filter('.searchItemSelected');
            var nextNode;

            switch (key)
            {
                case 38:
                    nextNode = selected.prev();
                    break;
                case 40:
                    nextNode = selected.next();
                    break;
                case 13:
                    if (items.hasClass('searchItemSelected'))
                        selected.find('.searchItemLink').trigger('click');
                    return false;
                    break;
            }

            if (nextNode.is && nextNode.is('li'))
            {
                selected.removeClass('searchItemSelected');
                nextNode.addClass('searchItemSelected');

                var container = $('#searchFrameDiv');
                var containerTop = container.scrollTop();
                var nextTop = nextNode.position().top;
                var nextHeight = nextNode.height();
                var selectedTop = selected.position().top;
                var topOff = $('#searchBarDiv').height() + $('#searchToggleBarDiv').height();
                var maxHeight = $(window).height();

                if(selectedTop > maxHeight - nextHeight || selectedTop < topOff)
                {
                    container.stop().animate({scrollTop: containerTop + nextTop - container.height()/2 + nextHeight/2}, 0);
                }
                else if(nextTop > maxHeight - nextHeight - 10 || nextTop < topOff + 10)
                {
                    container.stop().animate({scrollTop: containerTop - (selectedTop - nextTop)}, 0);
                }

                writeCookie('searchLastSelection', nextNode.text().hash() + nextNode.find('a').attr('href'), null);
            }
        }
    };

    $('#searchInput').bind('keydown keypress', function(e)
    {
        if (e.keyCode == 38 || e.keyCode == 40)
            e.preventDefault();
    });

    var oldSearch = readCookie('searchInput');
    if (oldSearch)
        $('#searchInput').val(oldSearch);

    if (readCookie('searchOpen') == "true")
    {
        $('#nav-tree').hide();
        $('#searchContainerDiv').css('height', '100%');

        buildList(list, $('#searchInput').val().ltrim().rtrim().doublewhitetrim(), searchFilter, searchType);
        highlightContents();

        $('#searchToggleBarSpan').text("Open Search");
        setFocusToInput();
    }
    else
    {
        $('#nav-tree').show();
        $('#searchContainerDiv').css('height', '21px');
        $('#searchToggleBarSpan').text("Close Search");
    }

    toggleElements();

    $('#searchBarMagIconDiv').hover(function()
    {
        $('#searchSelectWindow').stop().height('auto').slideDown(150);
    },
    function()
    {
        $('#searchSelectWindow').stop().slideUp(75);
    });

    $('#searchFilter').find('.SelectItem').click(function()
    {
        writeCookie('searchFilter', $('.itm', this).text(), null);
        searchFilter = $('.itm', this).text();

        $('#searchFilter').find('.SelectionMark').html("&#160;");
        $('.SelectionMark', this).html("&#8226;");
        $('#searchInput').trigger('keyup');
    });

    $('#searchType').find('.SelectItem').click(function()
    {
        writeCookie('searchType', $('.itm', this).text(), null);
        searchType = $('.itm', this).text();

        $('#searchType').find('.SelectionMark').html("&#160;");
        $('.SelectionMark', this).html("&#8226;");
        $('#searchInput').trigger('keyup');
    });

    $('#searchToggleBarDiv').click(function()
    {
        toggleSearch();
    });

    $('#searchFrameDiv').scroll(function() {
        writeCookie('searchPosY', $('#searchFrameDiv').scrollTop(), null);
    });

	var offset = 4;
	if ($("#nav-path").length > 0)	offset = 37

    $(window).resize(function()
    {
        $('#searchFrameDiv').height(getMaxHeight() - offset);
    });

    $(window).resize();
});

function buildList(list, searchInput, searchFilter, searchType)
{
    var htmlData = "";
    var tmpData = [];
    var itmName, liClass, itm, itmParent, source, parts, outp;
    var pos = 0;

    var ss = searchInput.toLowerCase();
    var oldSelection = readCookie('searchLastSelection');

	var si = searchInput.split(" ").join("");
	var sil = si.length;

	if (sil > 1)
	{
		for (var i=0; i<data.length; ++i )
		{
			itmName = data[i][0];
			if (data[i][3] != searchFilter && searchFilter != "All") continue;

			if(searchInput != "")
			{
				if(searchType == "Contains...")
					if(!itmName.containsAll(searchInput)) continue;

				if(searchType == "Starts with...")
					if(itmName.toLowerCase().indexOf(ss) != 0) continue;

				if(searchType == "Ends with...")
					if(!new RegExp(ss+"$").test(itmName.toLowerCase())) continue;

				if(searchType == "RegEx")
				{
					try
					{
						if(!new RegExp(searchInput).test(itmName)) continue;
					}
					catch(err)
					{
						tmpData = [];
						break;
					}
				}
			}

			data[i][4] = itmName.split(" ").join("").levenshtein(si);

			tmpData.push(data[i]);
		}
	}

    if(searchInput=='')
    {
        tmpData.sort(function(a, b)
        {
            return a[0] > b[0] ? 1 : -1;
        });
    }
    else
    {
        tmpData.sort(function(a, b)
        {
            return a[4] > b[4] ? 1 : -1;
        });
    }

    for (var i=0; i < tmpData.length && i < 500; ++i) // a_block: increased max results to 500
    {
        if (tmpData[i][3] != searchFilter && searchFilter != "All") continue;

        tmpData[i][2] != "" ? itmParent = " ("+ tmpData[i][2] + ")" : itmParent = "";

        outp = "";
        source = tmpData[i][0];

        parts = searchType == "RegEx" ? new RegExp(searchInput).exec(source) : ss.split(" ");

        for (j = 0; j < parts.length; j++)
        {
            itm = parts[j];
            pos = source.toLowerCase().indexOf(itm);

            if (pos != -1)
            {
                outp += source.substring(0, pos) + '<span class="highlight">' + source.substring(pos, pos+itm.length) + '</span>';
                source = source.substring(pos+itm.length);
            }
        }
        outp += source;

        liClass = 'searchItem'
        if (oldSelection && oldSelection != "false")
        {
            var str = $("<div/>").html(tmpData[i][0] + itmParent).text();
            if(str.hash() + tmpData[i][1] == oldSelection)
                liClass += ' searchItemSelected';
        }
        else
        {
            if(i == 0)
                liClass += ' searchItemSelected';
        }

        htmlData += '<li class="' + liClass + '"><a class="searchItemLink" href="' + tmpData[i][1] + '" rel="' + tmpData[i][3] + '" target="_top"><span class="searchItemName">' + outp + '</span><span class="searchParentItem">' + itmParent + '</span></a></li>';
    };

    if (tmpData.length == 0 && sil > 1)
        htmlData += '<div class="searchInfoTxt">Sorry, no matching entries found.</div>';

	if (tmpData.length > 500) // a_block: increased max results to 500
	{
		htmlData += '<div class="searchInfoTxt" style="margin-top: 5px;">Showing first 500 of ' + tmpData.length + ' results.</div>';
    }

	if (sil <= 1)
	{
		htmlData += '<div class="searchInfoTxt">Please input more than one character.</div>';
    }

    list.html(htmlData);

    $('.searchItemLink').click(function(e)
    {
        e.preventDefault();

        var url = $(this).attr('href');
        writeCookie('searchLastSelection', $(this).text().hash() + url, null);

        $('#searchFrameDiv li').removeClass('searchItemSelected');
        $(this).parent('.searchItem').addClass('searchItemSelected');

        location.href = url;

        highlightContents()
        setFocusToInput();
    });
}

function resetSearch()
{
    writeCookie('searchLastSelection', false, null);

    $('#searchFrameDiv li').removeClass('searchItemSelected');

    $('#searchInput').val('');
    $('#searchInput').trigger('keyup');
}

function toggleSearch()
{
    var ss = $('#searchInput').val().ltrim().rtrim().doublewhitetrim();

    if ($('#searchToggleBarSpan').text() == "Open Search")
    {
        if($('.searchItem').length == 0)
            $('#searchInput').trigger('keyup');

        if(ss == "")
        {
            writeCookie('searchLastSelection', false, null);
            var items = $('#searchFrameDiv li');
            items.removeClass('searchItemSelected');
            items.first().addClass('searchItemSelected');
        }

        $('#searchContainerDiv').animate({height: $(window).height() + "px"}, 150, function(){
            $('#nav-tree').hide();
            setFocusToInput();
            $('#searchContainerDiv').css({height:"100%"});

            highlightContents();
        });

        writeCookie('searchOpen', true, null);
    }
    else
    {
        $('#nav-tree').show();
        $('#searchContainerDiv').animate({height: "21px"}, 150, function(){
            (function (){
                try {
                  var navtree=$('#nav-tree');
                  navtree.scrollTop(navtree.scrollTop() + navtree.find('#selected').offset().top - 500);  // a_block: increased max results to 500
                } catch (err) {
                  setTimeout(arguments.callee, 0);
                }
            })();
        });

        if (ss == "")
        {
            writeCookie('searchPosY', 0, null);
            writeCookie('searchLastSelection', false, null);
        }

        $('.doc-content').removeHighlight();

        writeCookie('searchOpen', false, null);
    }

    toggleElements();
}

function toggleElements()
{
    if ($('#searchToggleBarSpan').text() == "Open Search")
    {
        $('#searchToggleBarSpan').text("Close Search");

        if ($('#searchInput').attr('value') != "")
        {
            $('#searchBarCloseIconDiv').show();
        }
        else
        {
            $('#searchBarCloseIconDiv').hide();
        }

        var oldPos = readCookie('searchPosY');
        if (oldPos)
            $('#searchFrameDiv').stop().animate({scrollTop: oldPos }, 0.001);
    }
    else
    {
        $('#searchToggleBarSpan').text("Open Search");
    }
}

function highlightContents()
{
    $('.doc-content').removeHighlight();

    var itm = $('.searchItemSelected').first();
    var txt = itm.find('.searchItemName').text();
    var rel = itm.find('a').attr('rel');
    var id = itm.find('a').attr('href');

    if(id)
        id = id.substring(id.indexOf("#") + 1);

    if(txt.indexOf("::") != -1)
    {
        txt = txt.substring(txt.indexOf("::")+2);
        txt = txt.substring(0, txt.indexOf("("));
    }

    if(txt.indexOf("<") != -1)
        txt = txt.substring(0, txt.indexOf("<"));

    if(txt != 'Sorry, no matching entries found.')
    {
        if (id && rel !== "Files" && rel !== "Classes" && rel !== "Enumvalues")
            $('a[id = "' + id + '"]').nextAll().find('.memproto').first().highlight(txt, 'highlight');

        if (rel == "Files" || rel == "Classes" || rel == "Groups" || rel == "Pages")
            $('.headertitle').highlight(txt, 'highlight');

        if (rel == "Enumvalues")
            $('.fieldname em').highlight(txt, 'highlight');

        if (rel == "Defines")
        {
            $('tr.memitem\\:' + id).find('.memItemRight').first().highlight(txt, 'highlight');
            var tmp = $('tr.memitem\\:g' + id);
            if (tmp !== undefined && tmp[0])
            {
                tmp.find('.memItemRight').first().highlight(txt, 'highlight');
                var cnt = $('#doc-content');
                var sh = cnt.find('div.highlight').first();
                if(sh !== undefined && sh.position() != null)
                    cnt.animate({scrollTop: cnt.scrollTop() + sh.position().top}, 0.001);
            }
        }
    }
}

function setFocusToInput()
{
    var oldPos = readCookie('searchInputPos');
    if (!oldPos)
        oldPos = 0;

    $('#searchInput').setSelection(oldPos, oldPos);
    setTimeout("$('#searchInput').focus()", 1);
}

function getMaxHeight()
{
    return $(window).height() - $('#searchBarDiv').height() - $('#searchToggleBarDiv').height();
}

String.prototype.ltrim = function()
{
    return this.replace(/^\s+/,"");
}

String.prototype.rtrim = function()
{
    return this.replace(/\s+$/,"");
}

String.prototype.doublewhitetrim = function()
{
    return this.replace(/\s{2,}/g, " ");
}

String.prototype.levenshtein = function(c)
{
	if (c.length <= 1) return 1

    var i, j, len1, len2;
    var d = new Array();

    var source = this.split("");
    var target = c.split("");

    len1 = source.length;
    len2 = target.length;

    if(len1 == 0)
        return len2;

    if(len2 == 0)
        return len1;

    for (i = 0; i <= len1; i++)
    {
        d[i] = new Array();
        d[i][0] = i;
    }

    for (j = 0; j <= len2; j++)
        d[0][j] = j;

    for (i = 1; i <= len1; i++)
    {
        for (j = 1; j <= len2; j++)
        {
            d[i][j] = Math.min(Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1), d[i - 1][j - 1] + (source[i - 1] == target[j - 1] ? 0 : 1));

            if (i > 1 && j > 1 && source[i] == target[j - 1] && source[i - 1] == target[j])
                d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + (source[i - 1] == target[j - 1] ? 0 : 1));
        }
    }

    return d[len1][len2];
};

String.prototype.containsAll = function(c)
{
    var original = this.toLowerCase();
    var clow = c.toLowerCase();
    var pos;

    if(original.indexOf(clow) != -1) return true;

    var target = clow.split(" ");
    if (target.length == 0)
        target.push(clow);

    for (i = 0; i < target.length; i++)
    {
        pos = original.indexOf(target[i]);
        if (pos == -1) return false;
        original = original.substring(pos+target[i].length);
    }

    return true;
}

String.prototype.hash = function()
{
    var hash = 0;
    if (this.length == 0) return hash;

    for (i = 0; i < this.length; i++)
    {
        char = this.charCodeAt(i);
        hash = ((hash<<5)-hash) + char;
        hash = hash & hash;
    }
    return hash;
}

$.fn.highlight = function(c, spanClass)
{
    var c = c.ltrim();
    if (c == "")
        return;

    var set = false;
    return this.each(function()
    {
        if(!set && this.textContent !== undefined && this.textContent.indexOf(c) != -1)
        {
            var container = this,
                content = container.innerHTML,
                highlighted = '<div id="highlight" ' + ( spanClass ? 'class="' + spanClass + '"' : '' ) + '>' + content + '</div>';

            container.innerHTML = highlighted;

            set = true;
        }
    });
}

jQuery.fn.removeHighlight = function()
{
     return $(".highlight").contents().unwrap();
};

function readCookie(cookie)
{
    if (window.chrome)
    {
        var val = $.totalStorage("doxygenMSearch_" + cookie + "_sdk");
        return val ? String(val) : false;
    }
    else
    {
        var myCookie = "doxygenMSearch_" + cookie  + "_sdk" + "=";

        if (document.cookie)
        {
            var index = document.cookie.indexOf(myCookie);

            if (index != -1)
            {
                var valStart = index + myCookie.length;
                var valEnd = document.cookie.indexOf(";", valStart);

                if (valEnd == -1)
                    valEnd = document.cookie.length;

                var val = document.cookie.substring(valStart, valEnd);

                return val;
            }
        }

        return false;
    }
}

function writeCookie(cookie, val, expiration)
{
    if (val==undefined) return;

    if (window.chrome)
    {
        $.totalStorage("doxygenMSearch_" + cookie + "_sdk", val);
    }
    else
    {
        if (expiration == null)
        {
            var date = new Date();
            date.setTime(date.getTime()+(10*365*24*60*60*1000));
            expiration = date.toGMTString();
        }

        document.cookie = "doxygenMSearch_" + cookie  + "_sdk" + "=" + val + "; expires=" + expiration+"; path=/";
    }
}

